  function normalizedOrderStatus(status,cancelType){const s=String(status??'').trim().toLowerCase(),c=String(cancelType??'').trim().toLowerCase();if(c.includes('return')||c.includes('refund')||s.includes('return')||s.includes('refund'))return'Return requested';if(s.includes('cancel')||c.includes('cancel'))return'Cancelled';if(s==='completed'||s==='complete'||s==='delivered')return'Delivered';if(s==='shipped'||s==='in transit')return'Shipped';if(s==='to ship'||s==='awaiting shipment'||s==='awaiting collection'||s==='processing')return'Ready to ship';return''}
