      if(!order){order={sourceKey,sourceOrderId:sourceId,platform,statuses:new Set(),rows:[],lineMap:new Map(),amounts:new Set(),created:cellText(row,columns.created),paid:cellText(row,columns.paid),tracking:cellText(row,columns.tracking),refund:cellText(row,columns.refund)};grouped.set(sourceKey,order)}
      order.statuses.add(status);const sellerSku=cellText(row,columns.sku),skuId=cellText(row,columns.skuId),catalogProduct=state.products.find(p=>[sellerSku,skuId].some(code=>code&&p.sku.toLowerCase()===code.toLowerCase())),sku=catalogProduct?.sku||sellerSku||skuId||cellText(row,columns.product)||'Unidentified item',label=catalogProduct?.name||cellText(row,columns.product)||sku,variant=cellText(row,columns.variant);
      if(!catalogProduct)unmapped.add(sku);
